  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_dict = {n['id']: n for n in nodes}
    parent_children = {}
    root_id = None
    for n in nodes:
        nid = n['id']
        parent = n['parent']
        if parent is None:
            root_id = nid
        else:
            parent_children.setdefault(parent, []).append(nid)
    # Initial retained set and symbol counts
    retained = set(n['id'] for n in nodes)
    symbol_count = {}
    for n in nodes:
        sym = n['symbol']
        symbol_count[sym] = symbol_count.get(sym, 0) + 1
    # Build processing order: deeper first, then by id ascending
    order = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    for node in order:
        nid = node['id']
        if not node['removable']:
            continue
        if nid == root_id:
            continue
        if node['symbol'] in required_symbols:
            continue
        # Check no retained children
        if any(cid in retained for cid in parent_children.get(nid, [])):
            continue
        # Check that required symbols remain after removal (redundant due to skip above, but safe)
        # Remove node
        removed.append(nid)
        retained.remove(nid)
        sym = node['symbol']
        symbol_count[sym] -= 1
    retained_ids = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_ids}"
}
